import random, time, uuid
import requests

URL = "https://api.example.com/v1/payments"
RETRY = {429, 502, 503, 504}

def create_payment(payload, tries=5):
    # ONE key, sent on every attempt
    key = str(uuid.uuid4())
    for n in range(tries):
        try:
            r = requests.post(
                URL,
                json=payload,  # JSON + header
                headers={"Idempotency-Key": key},
                timeout=10,  # never hang
            )
        except (requests.Timeout,
                requests.ConnectionError):
            r = None  # outcome unknown
        if r is not None:
            if r.status_code not in RETRY:
                r.raise_for_status()  # 4xx
                return r.json()
            hint = r.headers.get("Retry-After")
        else:
            hint = None
        # backoff 1, 2, 4... capped, plus jitter
        wait = float(hint or min(30, 2**n))
        time.sleep(wait + random.uniform(0, 1))
    raise RuntimeError("payments unavailable")

