async function createOrder(order, token) {
  const res = await fetch(`${API}/orders`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
    },
    body: JSON.stringify(order), // not automatic
  })
  if (res.status === 422) {
    const problem = await res.json()
    return { fieldErrors: problem.errors }
  }
  if (!res.ok) {
    throw new Error(`POST order: ${res.status}`)
  }
  return { order: await res.json() }
}

